using SkiaSharp;
var source="huashu-bird-sticker/stickers/Passeriformes/Muscicapidae/Phoenicurus_fuliginosus.webp";
using var original=SKBitmap.Decode(source)??throw new IOException("Icon sticker could not be decoded");
var sizes=new[]{16,24,32,48,64,128,256};var frames=new List<byte[]>();
foreach(var size in sizes){using var bitmap=new SKBitmap(size,size,SKColorType.Bgra8888,SKAlphaType.Premul);using(var canvas=new SKCanvas(bitmap)){canvas.Clear(SKColors.Transparent);var scale=(size-2.0f)/Math.Max(original.Width,original.Height);var w=original.Width*scale;var h=original.Height*scale;using var paint=new SKPaint{IsAntialias=true,FilterQuality=SKFilterQuality.High};canvas.DrawBitmap(original,new SKRect((size-w)/2,(size-h)/2,(size+w)/2,(size+h)/2),paint);}using var image=SKImage.FromBitmap(bitmap);using var data=image.Encode(SKEncodedImageFormat.Png,100);frames.Add(data.ToArray());}
Directory.CreateDirectory("app/Bird.App/Assets");using var stream=File.Create("app/Bird.App/Assets/bird.ico");using var writer=new BinaryWriter(stream);writer.Write((ushort)0);writer.Write((ushort)1);writer.Write((ushort)sizes.Length);var offset=6+16*sizes.Length;for(var i=0;i<sizes.Length;i++){writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)(sizes[i]==256?0:sizes[i]));writer.Write((byte)0);writer.Write((byte)0);writer.Write((ushort)1);writer.Write((ushort)32);writer.Write(frames[i].Length);writer.Write(offset);offset+=frames[i].Length;}foreach(var frame in frames)writer.Write(frame);Console.WriteLine("Generated seven-size icon from original Phoenicurus_fuliginosus sticker.");
